<script setup>
import { computed, onMounted, ref } from 'vue'; import { request } from '../api'; import { useAuthStore } from '../stores/auth'; import { useRoute, useRouter } from 'vue-router'
const auth=useAuthStore(); const route=useRoute(); const router=useRouter(); const credentials=ref([]); const loading=ref(true); const error=ref(''); const form=ref({name:'',kind:'file',file_path:'',file_mode:'0600',env_name:'',secret:''}); const isNew=computed(()=>route.name==='new-credential')
async function load(){try{const data=await request('/credentials?limit=100',{},auth.token);credentials.value=data.credentials||[]}catch(e){error.value=e.message}finally{loading.value=false}}
async function create(){error.value='';try{await request('/credentials',{method:'POST',body:JSON.stringify({...form.value,file_mode:form.value.kind==='file'?parseInt(form.value.file_mode,8):undefined,file_path:form.value.kind==='file'?form.value.file_path:undefined,env_name:form.value.kind==='env'?form.value.env_name:undefined})},auth.token);router.push('/credentials');load()}catch(e){error.value=e.message}}
onMounted(load)
</script>
<template><section class="surface-page"><header class="page-heading"><div><h1>{{isNew?'New credential':'Credentials'}}</h1><p>{{isNew?'Create reusable secret material for future Workspace provisioning':'Reusable secrets for future Workspace provisioning'}}</p></div><router-link v-if="!isNew" class="button primary" to="/credentials/new">New credential</router-link></header><div v-if="isNew" class="credential-layout"><form class="panel credential-form" @submit.prevent="create"><h2>Credential details</h2><label>Name<input v-model="form.name" required></label><fieldset><legend>Kind</legend><button type="button" :class="{selected:form.kind==='file'}" @click="form.kind='file'">File</button><button type="button" :class="{selected:form.kind==='env'}" @click="form.kind='env'">Environment</button></fieldset><label v-if="form.kind==='file'">Target path<input v-model="form.file_path" placeholder="/root/.ssh/id_ed25519" required></label><label v-else>Environment name<input v-model="form.env_name" placeholder="NPM_TOKEN" required></label><label v-if="form.kind==='file'">File mode<select v-model="form.file_mode"><option>0600</option><option>0400</option></select></label><label>Secret<textarea v-model="form.secret" required autocomplete="off"></textarea><small>Stored encrypted and never returned after creation.</small></label><footer><button type="button" @click="router.push('/credentials')">Cancel</button><button class="primary">Create</button></footer></form><aside class="callout"><h2>Binding semantics</h2><p>Credentials are write-only after creation.</p><p>Workspaces receive a snapshot at creation time.</p><p>Updating or deleting affects future Workspaces only.</p><p>Destroy a Workspace to revoke its injected snapshot.</p></aside></div><template v-else><div class="credential-note panel">Credentials are write-only after creation.</div><p v-if="loading" class="muted">Loading credentials…</p><div class="credential-table"><div class="credential-head"><span>Name</span><span>Ref</span><span>Kind</span><span>Target</span><span>Updated</span></div><div v-for="credential in credentials" :key="credential.ref" class="credential-row"><strong>{{credential.name}}</strong><span>{{credential.ref}}</span><span class="pill" :class="credential.kind==='env'?'blue':'amber'">{{credential.kind}}</span><span>{{credential.env_name || credential.file_path}}</span><span>{{new Date(credential.updated_at).toLocaleDateString()}}</span></div></div><div class="callout wide"><h2>Workspace binding is a snapshot</h2><p>Updating or deleting a Credential affects future Workspaces only. Existing Workspaces retain the values injected at creation.</p></div></template><p v-if="error" class="error">{{error}}</p></section></template>
